<form class="mail-mark-actions" method="post" action="/app/actions/central_contas/message_mark.php" data-mail-mark-form><?= csrf_field() ?><input type="hidden" name="message_id" value="<?= (int)$listMessage['id'] ?>"><input type="hidden" name="return_account" value="<?= $mailTab==='messages'?(int)$account:0 ?>"><input type="hidden" name="return_folder" value="<?= mailCenterEscape($mailTab==='messages'?(string)$folderId:($unifiedFolder??'all')) ?>"><input type="hidden" name="return_mark" value="<?= mailCenterEscape($markFilter??'all') ?>">
